// --- Local Storage Helpers ---

const STORAGE_KEYS = {
  CHAT_SESSIONS: 'mg_local_chat_sessions',
  CHAT_MESSAGES: 'mg_local_chat_messages',
  TASKS: 'mg_local_tasks',
  JOURNAL: 'mg_local_journal',
  TICKETS: 'mg_local_tickets',
  FEEDBACK: 'mg_local_feedback',
  CUSTOM_STRAINS: 'mg_custom_strains',
  PLANTS: 'mg_local_plants',
  DIAGNOSES: 'mg_local_diagnoses'
};

const getLocal = (key: string) => {
  try { return JSON.parse(localStorage.getItem(key) || '[]'); } catch { return []; }
};

const setLocal = (key: string, data: any) => {
  localStorage.setItem(key, JSON.stringify(data));
};

const keepLocal = (key: string, value: any, error?: any) => {
  const values = getLocal(key);
  const localValue = {
    ...value,
    sync_status: error && !isTransientPersistenceError(error) ? 'blocked' : 'pending',
    local_saved_at: new Date().toISOString(),
  };
  if (!values.some((item: any) => item.id === localValue.id)) values.push(localValue);
  setLocal(key, values);
  return localValue;
};

/**
 * Helper to convert Base64 string to Blob for upload.
 */
const base64ToBlob = (base64: string, contentType: string = 'image/jpeg'): Blob => {
  const base64Data = base64.includes(',') ? base64.split(',')[1] : base64;
  const byteCharacters = atob(base64Data);
  const byteArrays = [];

  for (let offset = 0; offset < byteCharacters.length; offset += 512) {
    const slice = byteCharacters.slice(offset, offset + 512);
    const byteNumbers = new Array(slice.length);
    for (let i = 0; i < slice.length; i++) {
      byteNumbers[i] = slice.charCodeAt(i);
    }
    const byteArray = new Uint8Array(byteNumbers);
    byteArrays.push(byteArray);
  }

  return new Blob(byteArrays, { type: contentType });
};

/**
 * Uploads an image to Supabase Storage 'user_uploads' bucket.
 * For anonymous users, this returns null (local images handled via base64 in UI).
 */
export const uploadImage = async (base64: string, path: string): Promise<string | null> => {
  if (!supabase) return null;
  try {
    const { data: { session } } = await supabase.auth.getSession();
    if (!session) return null; // Skip upload for anonymous users

    const blob = base64ToBlob(base64);
    const { error: uploadError } = await supabase.storage
      .from('user_uploads')
      .upload(path, blob, { contentType: 'image/jpeg', upsert: true });

    if (uploadError) throw uploadError;

    const { data: { publicUrl } } = supabase.storage.from('user_uploads').getPublicUrl(path);
    return publicUrl;
  } catch (error) {
    console.error('Error uploading image:', error);
    return null;
  }
};

const defaultPlantImage = 'https://images.unsplash.com/photo-1603796846097-b36976ea2851';

const normalizeEntryType = (type?: string) => {
  if (type === 'Health Check' || type === 'diagnosis') return 'diagnosis';
  if (type === 'chat') return 'chat';
  return 'note';
};

const mapJournalRow = (row: any) => ({
  id: row.id,
  date: row.created_at ? new Date(row.created_at).toLocaleDateString() : new Date().toLocaleDateString(),
  type: row.entry_type === 'diagnosis' ? 'Health Check' : row.entry_type || 'note',
  title: row.entry_type === 'diagnosis' ? 'Health Check' : 'Note',
  notes: row.content,
  imageUri: row.media_url,
  image: row.media_url,
  tags: row.tags || [],
  aiAnalysis: row.ai_analysis?.summary ? row.ai_analysis : (row.ai_analysis ? { summary: String(row.ai_analysis) } : undefined),
  diagnosisData: row.ai_analysis?.diagnosisData,
});

const mapTaskRow = (row: any): GrowTask => ({
  id: String(row.id),
  plantId: row.plant_id || undefined,
  title: row.title,
  isCompleted: Boolean(row.is_completed),
  completed: Boolean(row.is_completed),
  dueDate: row.due_date,
  source: row.source || 'user',
  createdAt: row.created_at,
  type: row.type || 'other',
  recurrence: row.recurrence || undefined,
  notes: row.notes || undefined,
});

const mapPlantRow = (row: any, journal: any[], tasks: GrowTask[], streak: number): Plant => {
  const strainDetails = row.strain_details || STRAIN_DATABASE.find(s => s.name === row.strain);
  return {
    id: row.id,
    name: row.name || `My ${row.strain || 'Plant'}`,
    strain: row.strain || 'Generic',
    strainDetails,
    stage: row.stage || 'Seedling',
    healthScore: row.health_score ?? 100,
    daysInStage: row.days_in_stage ?? 1,
    imageUri: row.image_url || defaultPlantImage,
    totalDays: row.total_days ?? 1,
    journal,
    tasks,
    streak,
    weeklySummaries: [],
  };
};

const growInitialization = new Map<string, Promise<string | null>>();

async function createOrReadDefaultGrow(): Promise<string | null> {
  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok || !profile.user?.id) {
    logOperationError('ensure_default_grow.profile', profile.error, true);
    return null;
  }
  const userId = profile.user.id;

  const { data: existing, error: existingError } = await supabase
    .from('grows')
    .select('id')
    .eq('user_id', userId)
    .order('created_at', { ascending: true })
    .limit(1)
    .maybeSingle();

  if (existingError) {
    logOperationError('ensure_default_grow.lookup', existingError, true);
    return null;
  }
  if (existing?.id) return existing.id;

  const { data, error } = await supabase
    .from('grows')
    .insert({ user_id: userId, name: 'My Grow', status: 'active' })
    .select('id')
    .maybeSingle();

  if (error) {
    logOperationError('ensure_default_grow.insert', error, true);
    return null;
  }
  return data?.id || null;
}

export const ensureDefaultGrow = async (): Promise<string | null> => {
  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok || !profile.user?.id) return null;
  const existingPromise = growInitialization.get(profile.user.id);
  if (existingPromise) return existingPromise;
  const promise = createOrReadDefaultGrow().finally(() => growInitialization.delete(profile.user!.id));
  growInitialization.set(profile.user.id, promise);
  return promise;
};

const markQueueError = (items: any[], index: number, error: any) => {
  items[index] = { ...items[index], sync_status: isTransientPersistenceError(error) ? 'pending' : 'blocked' };
};

const persistCloudPlantIds = (plantIdMap: Map<string, string>) => {
  if (!plantIdMap.size) return;
  for (const key of [STORAGE_KEYS.JOURNAL, STORAGE_KEYS.DIAGNOSES, STORAGE_KEYS.TASKS]) {
    const items = getLocal(key);
    let changed = false;
    const updated = items.map((item: any) => {
      const cloudPlantId = plantIdMap.get(item.plant_id);
      if (!cloudPlantId) return item;
      changed = true;
      return { ...item, plant_id: cloudPlantId };
    });
    if (changed) setLocal(key, updated);
  }
};

/** Replays only pending local writes, in foreign-key dependency order. */
export const reconcilePendingPersistence = async (): Promise<void> => {
  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok || !profile.user?.id) return;
  const userId = profile.user.id;
  const growId = await ensureDefaultGrow();
  if (!growId) return;

  const plantIdMap = new Map<string, string>();
  const localPlants = getLocal(STORAGE_KEYS.PLANTS);
  for (let index = localPlants.length - 1; index >= 0; index--) {
    const plant = localPlants[index];
    if (plant.sync_status === 'blocked') continue;
    const result = await supabase.from('plants').insert({
      user_id: userId, grow_id: growId, name: plant.name, strain: plant.strain,
      strain_details: plant.strainDetails || null, stage: plant.stage,
      image_url: plant.imageUri || null, health_score: plant.healthScore ?? 100,
      days_in_stage: plant.daysInStage ?? 1, total_days: plant.totalDays ?? 1,
    }).select('id').single();
    if (result.error) markQueueError(localPlants, index, result.error);
    else { plantIdMap.set(plant.id, result.data.id); localPlants.splice(index, 1); }
  }
  setLocal(STORAGE_KEYS.PLANTS, localPlants);
  persistCloudPlantIds(plantIdMap);

  const replay = async (key: string, table: string, payloadFor: (item: any) => any | null) => {
    const items = getLocal(key);
    for (let index = items.length - 1; index >= 0; index--) {
      const item = items[index];
      if (item.sync_status === 'blocked') continue;
      const payload = payloadFor(item);
      if (!payload) continue;
      const { error } = await supabase.from(table).insert(payload);
      if (error) markQueueError(items, index, error);
      else items.splice(index, 1);
    }
    setLocal(key, items);
  };
  const cloudPlantId = (id: string | null | undefined) => {
    if (!id) return null;
    if (!id.startsWith('local_')) return id;
    return plantIdMap.get(id) || undefined;
  };

  await replay(STORAGE_KEYS.JOURNAL, 'journal_logs', item => {
    const plantId = cloudPlantId(item.plant_id);
    if (item.plant_id?.startsWith?.('local_') && !plantId) return null;
    return { user_id: userId, plant_id: plantId || null, entry_type: item.entry_type, content: item.content,
      media_url: item.media_url || null, tags: item.tags || [], ai_analysis: item.ai_analysis || null };
  });
  await replay(STORAGE_KEYS.DIAGNOSES, 'diagnosis_reports', item => {
    const plantId = cloudPlantId(item.plant_id);
    if (item.plant_id?.startsWith?.('local_') && !plantId) return null;
    return { user_id: userId, plant_id: plantId || null, image_url: item.image_url || null,
      diagnosis_json: item.diagnosis_json || null, confidence_score: item.confidence_score ?? null };
  });
  await replay(STORAGE_KEYS.TASKS, 'tasks', item => {
    const plantId = cloudPlantId(item.plant_id);
    if (item.plant_id?.startsWith?.('local_') && !plantId) return null;
    return { user_id: userId, plant_id: plantId || null, title: item.title, is_completed: Boolean(item.is_completed),
      due_date: item.due_date, source: item.source, type: item.type, recurrence: item.recurrence || null,
      notes: item.notes || null, created_at: item.created_at || new Date().toISOString() };
  });
  await replay(STORAGE_KEYS.TICKETS, 'support_tickets', item => ({ user_id: userId, name: item.name,
    email: item.email, issue: item.issue, message: item.message, status: item.status || 'open',
    created_at: item.created_at || new Date().toISOString() }));
  await replay(STORAGE_KEYS.FEEDBACK, 'user_feedback', item => ({ user_id: userId, rating: item.rating,
    message: item.message, created_at: item.created_at || new Date().toISOString() }));
};

export const createPlantRecord = async (strain: any): Promise<Plant | null> => {
  const { data: { session } } = await supabase.auth.getSession();
  const localPlant: Plant = {
    id: `local_plant_${Date.now()}`,
    name: `My ${strain.name || 'Plant'}`,
    strain: strain.name || 'Generic',
    strainDetails: strain,
    stage: 'Seedling',
    healthScore: 100,
    daysInStage: 1,
    imageUri: strain.image || strain.imageUri || defaultPlantImage,
    totalDays: 1,
    journal: [],
    tasks: [],
    streak: 0,
    weeklySummaries: [],
  };

  if (!session?.user?.id) return keepLocal(STORAGE_KEYS.PLANTS, localPlant) as Plant;

  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok) return keepLocal(STORAGE_KEYS.PLANTS, localPlant, profile.error) as Plant;
  const growId = await ensureDefaultGrow();
  if (!growId) return keepLocal(STORAGE_KEYS.PLANTS, localPlant) as Plant;
  const { data, error } = await supabase
    .from('plants')
    .insert({
      user_id: session.user.id,
      grow_id: growId,
      name: localPlant.name,
      strain: localPlant.strain,
      strain_details: strain,
      stage: localPlant.stage,
      image_url: localPlant.imageUri,
      health_score: localPlant.healthScore,
      days_in_stage: localPlant.daysInStage,
      total_days: localPlant.totalDays,
    })
    .select()
    .maybeSingle();

  if (error || !data) {
    logOperationError('create_plant', error, true);
    return keepLocal(STORAGE_KEYS.PLANTS, localPlant, error) as Plant;
  }

  return mapPlantRow(data, [], [], 0);
};

export const loadGrowData = async (streak: number): Promise<Plant[]> => {
  const { data: { session } } = await supabase.auth.getSession();
  if (!session?.user?.id) {
    const localPlants = getLocal(STORAGE_KEYS.PLANTS);
    return localPlants.length ? localPlants : [];
  }

  let { data: plantRows, error: plantError } = await supabase
    .from('plants')
    .select('*')
    .eq('user_id', session.user.id)
    .order('created_at', { ascending: true });

  if (plantError) {
    console.warn('loadGrowData plants failed:', plantError);
    return [];
  }

  if (!plantRows || plantRows.length === 0) {
    const created = await createPlantRecord(STRAIN_DATABASE[0]);
    plantRows = created && !created.id.startsWith('local_') ? [{
      id: created.id,
      name: created.name,
      strain: created.strain,
      strain_details: created.strainDetails,
      stage: created.stage,
      image_url: created.imageUri,
      health_score: created.healthScore,
      days_in_stage: created.daysInStage,
      total_days: created.totalDays,
    }] : [];
    if (created?.id.startsWith('local_')) return [created];
  }

  const [{ data: journalRows }, { data: taskRows }] = await Promise.all([
    supabase.from('journal_logs').select('*').eq('user_id', session.user.id).order('created_at', { ascending: false }),
    supabase.from('tasks').select('*').eq('user_id', session.user.id).order('created_at', { ascending: false }),
  ]);

  return (plantRows || []).map((plant: any) => {
    const plantJournal = (journalRows || []).filter((row: any) => row.plant_id === plant.id).map(mapJournalRow);
    const plantTasks = (taskRows || []).filter((row: any) => row.plant_id === plant.id).map(mapTaskRow);
    return mapPlantRow(plant, plantJournal, plantTasks, streak);
  });
};

/**
 * Saves a new entry to the journal_logs table (or Local Storage).
 */
export const saveJournalEntry = async (entry: {
  plant_id: string;
  entry_type: 'text' | 'photo' | 'draw' | 'diagnosis' | 'chat';
  content: string;
  media_url?: string;
  tags: string[];
  ai_analysis?: any;
}) => {
  const { data: { session } } = await supabase.auth.getSession();

  const newEntry = {
    id: `local_${Date.now()}`,
    user_id: session?.user.id || 'anon',
    plant_id: entry.plant_id || null,
    entry_type: entry.entry_type,
    content: entry.content,
    media_url: entry.media_url,
    tags: entry.tags,
    ai_analysis: entry.ai_analysis,
    created_at: new Date().toISOString()
  };

  if (!session || entry.plant_id?.startsWith('local_')) return keepLocal(STORAGE_KEYS.JOURNAL, newEntry);

  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok) return keepLocal(STORAGE_KEYS.JOURNAL, newEntry, profile.error);

  const { data, error } = await supabase
    .from('journal_logs')
    .insert({
      user_id: session.user.id,
      plant_id: entry.plant_id || null,
      entry_type: entry.entry_type,
      content: entry.content,
      media_url: entry.media_url,
      tags: entry.tags,
      ai_analysis: entry.ai_analysis,
    })
    .select()
    .maybeSingle();

  if (error) {
    logOperationError('save_journal_entry', error, true);
    return keepLocal(STORAGE_KEYS.JOURNAL, newEntry, error);
  }
  return data;
};

export const saveAppJournalEntry = async (plantId: string | undefined, entry: any) => {
  const imageData = entry.image || entry.imageUri;
  let mediaUrl = imageData;
  const { data: { session } } = await supabase.auth.getSession();

  if (session?.user?.id && imageData?.startsWith?.('data:image')) {
    const path = `${session.user.id}/journal/${Date.now()}.jpg`;
    mediaUrl = await uploadImage(imageData, path) || imageData;
  }

  const saved = await saveJournalEntry({
    plant_id: plantId || entry.plant_id || entry.plantId || '',
    entry_type: normalizeEntryType(entry.type) as any,
    content: entry.notes || entry.content || '',
    media_url: mediaUrl || undefined,
    tags: entry.tags || [],
    ai_analysis: entry.aiAnalysis || (entry.diagnosisData ? { diagnosisData: entry.diagnosisData } : undefined),
  });

  return mapJournalRow(saved || {
    id: `local_${Date.now()}`,
    created_at: new Date().toISOString(),
    entry_type: normalizeEntryType(entry.type),
    content: entry.notes || entry.content || '',
    media_url: mediaUrl,
    tags: entry.tags || [],
    ai_analysis: entry.aiAnalysis,
  });
};

export const saveDiagnosisReport = async (plantId: string | undefined, entry: any) => {
  const { data: { session } } = await supabase.auth.getSession();
  if (!entry?.diagnosisData) return null;

  const localDiagnosis = {
    id: `local_diagnosis_${Date.now()}`,
    user_id: session?.user.id || 'anon',
    plant_id: plantId || null,
    image_url: entry.imageUri || entry.image || null,
    diagnosis_json: entry.diagnosisData,
    confidence_score: entry.diagnosisData.confidence ?? null,
  };
  if (!session?.user?.id || plantId?.startsWith('local_')) {
    return keepLocal(STORAGE_KEYS.DIAGNOSES, localDiagnosis);
  }
  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok) return keepLocal(STORAGE_KEYS.DIAGNOSES, localDiagnosis, profile.error);

  const { error } = await supabase.from('diagnosis_reports').insert({
    user_id: session.user.id,
    plant_id: plantId && !plantId.startsWith('local_') ? plantId : null,
    image_url: entry.imageUri || entry.image || null,
    diagnosis_json: entry.diagnosisData,
    confidence_score: entry.diagnosisData.confidence ?? null,
  });

  if (error) {
    logOperationError('save_diagnosis_report', error, true);
    return keepLocal(STORAGE_KEYS.DIAGNOSES, localDiagnosis, error);
  }
  return true;
};

// --- Task Management System ---

export const getPendingTasksForToday = async (): Promise<GrowTask[] | null> => {
  const { data: { session } } = await supabase.auth.getSession();
  const today = new Date().toISOString().split('T')[0];

  if (!session) {
    const tasks = getLocal(STORAGE_KEYS.TASKS);
    return tasks
      .filter((t: any) => t.due_date <= today && !t.is_completed)
      .sort((a: any, b: any) => new Date(a.due_date).getTime() - new Date(b.due_date).getTime())
      .map((t: any) => ({
        id: t.id,
        plantId: t.plant_id,
        title: t.title,
        isCompleted: t.is_completed,
        completed: t.is_completed,
        dueDate: t.due_date,
        source: t.source,
        createdAt: t.created_at,
        type: t.type
      }));
  }

  const { data, error } = await supabase
    .from('tasks')
    .select('*')
    .eq('user_id', session.user.id)
    .lte('due_date', today)
    .eq('is_completed', false)
    .order('due_date', { ascending: true });

  if (error) return [];

  return (data || []).map((t: any) => ({
    id: t.id,
    plantId: t.plant_id,
    title: t.title,
    isCompleted: t.is_completed,
    completed: t.is_completed,
    dueDate: t.due_date,
    source: t.source,
    createdAt: t.created_at,
    type: t.type
  }));
};

export const addNewTask = async (task: Omit<GrowTask, 'id' | 'completed' | 'isCompleted' | 'createdAt'>): Promise<GrowTask | null> => {
  const { data: { session } } = await supabase.auth.getSession();

  const newTaskObj = {
    user_id: session?.user.id || 'anon',
    plant_id: task.plantId,
    title: task.title,
    is_completed: false,
    due_date: task.dueDate,
    source: task.source,
    type: task.type || 'other',
    recurrence: task.recurrence || null,
    notes: task.notes || null,
    created_at: new Date().toISOString()
  };

  if (!session || task.plantId?.startsWith('local_')) {
    const tasks = getLocal(STORAGE_KEYS.TASKS);
    const localTask = { ...newTaskObj, id: `local_${Date.now()}` };
    tasks.push(localTask);
    setLocal(STORAGE_KEYS.TASKS, tasks);

    // Return mapped format
    return {
      id: localTask.id,
      plantId: localTask.plant_id,
      title: localTask.title,
      isCompleted: localTask.is_completed,
      completed: localTask.is_completed,
      dueDate: localTask.due_date,
      source: localTask.source,
      createdAt: localTask.created_at,
      type: localTask.type,
      recurrence: localTask.recurrence,
      notes: localTask.notes
    };
  }

  const profile = await ensureProfileForCurrentUser();
  if (!profile.ok) {
    const localTask = { ...newTaskObj, id: `local_${Date.now()}` };
    keepLocal(STORAGE_KEYS.TASKS, localTask, profile.error);
    return mapTaskRow(localTask);
  }

  const { data, error } = await supabase
    .from('tasks')
    .insert(newTaskObj)
    .select()
    .single();

  if (error) {
    logOperationError('add_task', error, true);
    const localTask = { ...newTaskObj, id: `local_${Date.now()}` };
    keepLocal(STORAGE_KEYS.TASKS, localTask, error);
    return mapTaskRow(localTask);
  }

  return {
    id: data.id,
    plantId: data.plant_id,
    title: data.title,
    isCompleted: data.is_completed,
    completed: data.is_completed,
    dueDate: data.due_date,
    source: data.source,
    createdAt: data.created_at,
    type: data.type,
    recurrence: data.recurrence,
    notes: data.notes
  };
};

export const toggleTaskCompletion = async (taskId: string, isCompleted: boolean): Promise<boolean> => {
  const { data: { session } } = await supabase.auth.getSession();

  if (!session || taskId.startsWith('local_')) {
    const tasks = getLocal(STORAGE_KEYS.TASKS);
    const updated = tasks.map((t: any) => t.id === taskId ? { ...t, is_completed: isCompleted } : t);
    setLocal(STORAGE_KEYS.TASKS, updated);
    return true;
  }

  const { error } = await supabase
    .from('tasks')
    .update({ is_completed: isCompleted })
    .eq('id', taskId);

  return !error;
};

// --- Support & Feedback ---

export const createSupportTicket = async (ticket: { name: string, email: string, issue: string, message: string }) => {
  const { data: { session } } = await supabase.auth.getSession();
  let persistenceError: unknown = null;

  if (session?.user?.id) {
    const profile = await ensureProfileForCurrentUser();
    if (!profile.ok) {
      const localTicket = { ...ticket, user_id: session.user.id, id: `local_${Date.now()}`, created_at: new Date().toISOString() };
      keepLocal(STORAGE_KEYS.TICKETS, localTicket, profile.error);
      return localTicket;
    }
  }

  // Submit to DB if possible (RLS might allow anon insert, check policy)
  // If strict RLS, we fallback to just returning success since Email is the primary channel.
  try {
    const { data, error } = await supabase
      .from('support_tickets')
      .insert({
        user_id: session?.user.id || null,
        name: ticket.name,
        email: ticket.email,
        issue: ticket.issue,
        message: ticket.message,
        status: 'open',
        created_at: new Date().toISOString()
      })
      .select()
      .single();
    if (!error) return data;
    persistenceError = error;
    logOperationError('create_support_ticket', error, true);
  } catch (error) {
    persistenceError = error;
    logOperationError('create_support_ticket', error, true);
  }

  return keepLocal(STORAGE_KEYS.TICKETS, {
    ...ticket,
    user_id: session?.user.id || null,
    id: `local_${Date.now()}`,
    created_at: new Date().toISOString(),
  }, persistenceError);
};

export const submitUserFeedback = async (feedback: { rating: number, message: string }) => {
  const { data: { session } } = await supabase.auth.getSession();
  let persistenceError: unknown = null;
  if (session?.user?.id) {
    const profile = await ensureProfileForCurrentUser();
    if (!profile.ok) {
      const localFeedback = { ...feedback, user_id: session.user.id, id: `local_feedback_${Date.now()}`, created_at: new Date().toISOString() };
      return keepLocal(STORAGE_KEYS.FEEDBACK, localFeedback, profile.error);
    }
  }
  try {
    const { data, error } = await supabase
      .from('user_feedback')
      .insert({
        user_id: session?.user.id || null, // Allow null in DB scheme if possible
        rating: feedback.rating,
        message: feedback.message,
        created_at: new Date().toISOString()
      })
      .select()
      .single();
    if (!error) return data;
    persistenceError = error;
    logOperationError('submit_user_feedback', error, true);
  } catch (error) {
    persistenceError = error;
    logOperationError('submit_user_feedback', error, true);
  }
  const localFeedback = { ...feedback, id: `local_feedback_${Date.now()}`, created_at: new Date().toISOString(), sync_status: 'pending' };
  return keepLocal(STORAGE_KEYS.FEEDBACK, localFeedback, persistenceError);
};

export const submitAppRating = async (rating: number) => {
  const { data: { session } } = await supabase.auth.getSession();
  try {
    await supabase.from('app_ratings').insert({
      user_id: session?.user.id || null,
      rating: rating,
      created_at: new Date().toISOString()
    });
  } catch (e) { /* ignore */ }
  return { id: 'local-rating' };
};

// --- Chat History System (Mixed Mode) ---

export interface ChatSession {
  id: string;
  title: string;
  is_pinned: boolean;
  created_at: string;
}

export interface StoredMessage {
  id: string;
  session_id: string;
  role: 'user' | 'assistant';
  content: string;
  attachment_url?: string;
  attachment_type?: string;
  created_at: string;
}

export const createChatSession = async (title: string = "New Conversation"): Promise<ChatSession | null> => {
  const { data: { session } } = await supabase.auth.getSession();

  if (!session) {
    return createLocalSession(title);
  }

  const { data, error } = await supabase
    .from('chat_sessions')
    .insert({ user_id: session.user.id, title })
    .select()
    .single();

  if (error) {
    console.error("Create Session Error (Cloud):", error);
    // FALLBACK: If cloud fails, create local session instead of blocking the user
    return createLocalSession(title);
  }
  return data;
};

const createLocalSession = (title: string): ChatSession => {
  const newSession = {
    id: `local_session_${Date.now()}`,
    title,
    is_pinned: false,
    created_at: new Date().toISOString()
  };
  const sessions = getLocal(STORAGE_KEYS.CHAT_SESSIONS);
  sessions.unshift(newSession);
  setLocal(STORAGE_KEYS.CHAT_SESSIONS, sessions);
  return newSession;
};

// --- Custom Strains System ---

const normalizeCustomStrain = (
  strain: Partial<Strain> & Record<string, any>,
  fallbackId = `custom_${Date.now()}`,
): Strain => ({
  ...strain,
  id: strain.id || fallbackId,
  name: strain.name?.trim() || 'Unnamed strain',
  type: ['Indica', 'Sativa', 'Hybrid'].includes(strain.type || '') ? strain.type as Strain['type'] : 'Hybrid',
  thc_level: formatStrainValue(strain.thc_level),
  cbd_level: formatStrainValue(strain.cbd_level),
  most_common_terpene: formatStrainValue(strain.most_common_terpene),
  description: formatStrainValue(strain.description),
  userCreated: true,
});

export const getCustomStrains = (): Strain[] => {
  return getLocal(STORAGE_KEYS.CUSTOM_STRAINS).map((strain: Partial<Strain>, index: number) => {
    const normalizedName = strain.name?.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_') || 'unnamed';
    return normalizeCustomStrain(strain, `custom_legacy_${index}_${normalizedName}`);
  });
};

export const saveCustomStrain = (strain: Partial<Strain>): Strain => {
  const strains = getLocal(STORAGE_KEYS.CUSTOM_STRAINS);
  const newStrain = normalizeCustomStrain({ ...strain, id: `custom_${Date.now()}` });
  strains.unshift(newStrain); // Add to top
  setLocal(STORAGE_KEYS.CUSTOM_STRAINS, strains);
  return newStrain;
};

export const deleteCustomStrain = (id: string) => {
  const strains = getLocal(STORAGE_KEYS.CUSTOM_STRAINS);
  const updated = strains.filter((s: any) => s.id !== id);
  setLocal(STORAGE_KEYS.CUSTOM_STRAINS, updated);
};


export const getChatSessions = async (): Promise<ChatSession[]> => {
  const { data: { session } } = await supabase.auth.getSession();
  let sessions: ChatSession[] = [];

  // 1. Load Local
  const localSessions = getLocal(STORAGE_KEYS.CHAT_SESSIONS);
  sessions = [...localSessions];

  // 2. Load Cloud (if logged in)
  if (session) {
    const { data } = await supabase
      .from('chat_sessions')
      .select('*')
      .order('is_pinned', { ascending: false })
      .order('created_at', { ascending: false });
    if (data) sessions = [...sessions, ...data];
  }

  // Sort combined
  return sessions.sort((a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime());
};

export const deleteChatSession = async (sessionId: string) => {
  if (sessionId.startsWith('local_')) {
    const sessions = getLocal(STORAGE_KEYS.CHAT_SESSIONS);
    setLocal(STORAGE_KEYS.CHAT_SESSIONS, sessions.filter((s: any) => s.id !== sessionId));
    return;
  }
  await supabase.from('chat_sessions').delete().eq('id', sessionId);
};

export const pinChatSession = async (sessionId: string, isPinned: boolean) => {
  if (sessionId.startsWith('local_')) {
    const sessions = getLocal(STORAGE_KEYS.CHAT_SESSIONS);
    const updated = sessions.map((s: any) => s.id === sessionId ? { ...s, is_pinned: isPinned } : s);
    setLocal(STORAGE_KEYS.CHAT_SESSIONS, updated);
    return;
  }
  await supabase.from('chat_sessions').update({ is_pinned: isPinned }).eq('id', sessionId);
};

export const saveChatMessage = async (
  sessionId: string,
  role: 'user' | 'assistant',
  content: string,
  attachmentUrl?: string,
  attachmentType?: string
): Promise<StoredMessage | null> => {

  const newMessage = {
    id: `msg_${Date.now()}`,
    session_id: sessionId,
    role,
    content,
    attachment_url: attachmentUrl,
    attachment_type: attachmentType,
    created_at: new Date().toISOString()
  };

  if (sessionId.startsWith('local_')) {
    const messages = getLocal(STORAGE_KEYS.CHAT_MESSAGES);
    messages.push(newMessage);
    setLocal(STORAGE_KEYS.CHAT_MESSAGES, messages);
    return newMessage;
  }

  const { data, error } = await supabase
    .from('chat_messages')
    .insert({
      session_id: sessionId,
      role,
      content,
      attachment_url: attachmentUrl,
      attachment_type: attachmentType
    })
    .select()
    .single();

  if (error) { console.error("Save Message Error:", error); return null; }
  return data;
};

export const getChatMessages = async (sessionId: string): Promise<StoredMessage[]> => {
  if (sessionId.startsWith('local_')) {
    const messages = getLocal(STORAGE_KEYS.CHAT_MESSAGES);
    return messages
      .filter((m: any) => m.session_id === sessionId)
      .sort((a: any, b: any) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime());
  }

  const { data, error } = await supabase
    .from('chat_messages')
    .select('*')
    .eq('session_id', sessionId)
    .order('created_at', { ascending: true });

  if (error) return [];
  return data;
};

// --- Account Deletion ---

export const deleteUserData = async (): Promise<boolean> => {
  const { data: { session } } = await supabase.auth.getSession();

  // 1. Clear Local Storage
  localStorage.clear();

  // 2. Delete from Supabase (if authenticated)
  if (session?.user?.id) {
    const uid = session.user.id;
    try {
      // Execute deletions in parallel for speed, handle potential errors gracefully
      await Promise.all([
        supabase.from('profiles').delete().eq('id', uid),
        supabase.from('grow_logs').delete().eq('user_id', uid), // Assuming this is the table name from user request
        supabase.from('journal_logs').delete().eq('user_id', uid),
        supabase.from('tasks').delete().eq('user_id', uid),
        supabase.from('chat_sessions').delete().eq('user_id', uid),
        supabase.from('chat_messages').delete().eq('user_id', uid), // Dependent on session usually, but for completeness
        supabase.from('user_feedback').delete().eq('user_id', uid),
        supabase.from('support_tickets').delete().eq('user_id', uid),
        supabase.auth.signOut()
      ]);
      return true;
    } catch (e) {
      console.error("Error deleting user data from Supabase:", e);
      // Even if DB fails (e.g. network), we treated local clear as success for the user's perception on this device
      return false;
    }
  }

  return true; // Local only account deleted
};
